static void ApplyProcessPriority()
{
    if (!SetPriorityClass(GetCurrentProcess(), HIGH_PRIORITY_CLASS))
    {
        log::warning(
            "UVSR could not request High process priority (Win32 error %lu)",
            GetLastError());
    }
}

